import{_ as e,c as a,o as i,ae as t}from"./chunks/framework.Bi6zybwU.js";const c=JSON.parse('{"title":"Create Table from Custom SQL","description":"Create Table from Custom SQL","frontmatter":{"title":"Create Table from Custom SQL","description":"Create Table from Custom SQL"},"headers":[],"relativePath":"guide/data-sources/create-table-from-custom-sql.md","filePath":"guide/data-sources/create-table-from-custom-sql.md"}'),l={name:"guide/data-sources/create-table-from-custom-sql.md"};function n(r,s,h,o,p,d){return i(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="create-table-from-custom-sql" tabindex="-1">Create Table from Custom SQL <a class="header-anchor" href="#create-table-from-custom-sql" aria-label="Permalink to &quot;Create Table from Custom SQL&quot;">​</a></h1><p>One of the most versatile features of **Ninja Tables Pro **is the <strong>Custom SQL Query</strong>. You can create a table from your SQL database with the help of your custom SQL query. Here the table data is dynamically fetched. Each manual change in the database or in a plugin will be displayed on the table’s front end. For example, when you create a table from the WP user table, it will display all user data on the table. Once you have a new user, it synchronizes with your site&#39;s database table. After that, the table can be edited and redesigned like a default table.</p><h2 id="table-with-custom-sql-queries" tabindex="-1">Table with Custom SQL Queries <a class="header-anchor" href="#table-with-custom-sql-queries" aria-label="Permalink to &quot;Table with Custom SQL Queries&quot;">​</a></h2><p>Here is a simple table created in Ninja Tables using Custom SQL Query -</p><ul><li>Below you can notice a database table on the WordPress database called <strong>wp_buyers_table</strong>. You can easily create a table from this database table by writing a single-line query in Ninja Tables. <img src="https://ninjatables.com/wp-content/uploads/2023/01/create-table-from-custom-sql-1.png" alt="Create Table from Custom SQL"></li><li>First, go to the <strong>Add Table</strong> button and Custom SQL and name your table. Then write a custom SQL query: <em>SELECT * FROM “your-database-table-name”</em></li><li>For our wp_buyers_table it will be like this: <code>**SELECT * FROM </code>wp_buyers_table<code>**</code></li><li>And then click on the **Add **button. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Custom-SQL-Table-scaled.webp" alt=""></li><li>**Congratulations! **Your Table is now successfully created. You can alter the design of your table like you can with other tables. <img src="https://ninjatables.com/wp-content/uploads/2023/12/Ninja-Tables-Pro-%E2%80%B9-Demosite-%E2%80%94-WordPress-1-1.png" alt="Created Table"></li></ul><h2 id="some-conditional-query" tabindex="-1"><strong>Some Conditional Query</strong> <a class="header-anchor" href="#some-conditional-query" aria-label="Permalink to &quot;**Some Conditional Query**&quot;">​</a></h2><p>The data can be accessed conditionally from your database table. Here you can use the standard SQL coding method. You can set the condition of the data to fetch after the keyword WHERE.</p><h3 id="single-conditional-queries" tabindex="-1"><strong>Single Conditional Queries</strong> <a class="header-anchor" href="#single-conditional-queries" aria-label="Permalink to &quot;**Single Conditional Queries**&quot;">​</a></h3><p>So if a table is made from the wp_buyers_table table to display only book buyers then this structure should be followed. SEL<em>ECT * FROM <code>Your Database Table Name</code> WHERE columnName = &#39;yourFilterValue&#39;</em> For our wp_buyers_table it will be like this: <code>**SELECT * FROM </code>wp_buyers_table<code>WHERE products = &#39;book&#39;**</code><img src="https://ninjatables.com/wp-content/uploads/2023/12/create-table-from-custom-sql-4-edited.png" alt="Single Conditional Queries"></p><h3 id="multiple-conditional-queries" tabindex="-1"><strong>Multiple Conditional Queries</strong> <a class="header-anchor" href="#multiple-conditional-queries" aria-label="Permalink to &quot;**Multiple Conditional Queries**&quot;">​</a></h3><p>If a table is created to display book and computer buyers from the wp buyers table then this structure can be followed. <em>SELECT * FROM <code>wp_buyers_table</code> WHERE coloumnName = &#39;filterData1&#39; OR columnName= &#39;filterData2&#39;</em> For our wp_buyers_table it will be like this: <strong><code>SELECT * FROM </code>wp_buyers_table<code>WHERE products = &#39;book&#39;OR products = &#39;Computer’</code></strong><img src="https://ninjatables.com/wp-content/uploads/2023/12/create-table-from-custom-sql-5-edited.png" alt="Multiple Conditional Queries"></p><h2 id="few-basic-examples" tabindex="-1"><strong>Few Basic Examples</strong> <a class="header-anchor" href="#few-basic-examples" aria-label="Permalink to &quot;**Few Basic Examples**&quot;">​</a></h2><p>With respect to this <code>wp_buyers_table</code> all sample queries are written, you can write your own based on your table data. <img src="https://ninjatables.com/wp-content/uploads/2023/01/create-table-from-custom-sql-6.webp" alt="wp_buyers_table (database table)"></p><p>To grab the first five data:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_buyers_table`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>To fetch data except the first five:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_buyers_table`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>To get data on the first five that contain only book buyers:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_buyers_table`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;book&#39;</span></span></code></pre></div><p>To fetch the data of the first five except book buyers:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_buyers_table`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;book&#39;</span></span></code></pre></div><p>To get the data of the first five pen and computer buyers:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_buyers_table`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pen&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;computer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="advanced-custom-queries" tabindex="-1"><strong>Advanced Custom Queries</strong> <a class="header-anchor" href="#advanced-custom-queries" aria-label="Permalink to &quot;**Advanced Custom Queries**&quot;">​</a></h2><p>To write queries, some Dynamic Placeholders are available. Use this shortcode below on your queries to dynamically use the current user id, current date, current date-time, current post id, current post title, and prefix value.</p><ul><li><strong>Current user id:</strong> <code>{current_user_id}</code></li><li><strong>Current Date:</strong> <code>{current_date}</code></li><li><strong>Current Date Time:</strong> <code>{current_date_time}</code></li><li><strong>Current Post Id:</strong> <code>{current_post_id}</code></li><li><strong>Current Post Title:</strong> <code>{current_post_title}</code></li><li><strong>And Prefix:</strong> <code>{prefix}</code></li></ul><h2 id="examples-of-advanced-queries" tabindex="-1"><strong>Examples of Advanced Queries</strong> <a class="header-anchor" href="#examples-of-advanced-queries" aria-label="Permalink to &quot;**Examples of Advanced Queries**&quot;">​</a></h2><p>To create a table from our database table&#39;s wp-posts where the current user creates the data, it will be:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> wp_posts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> post_author </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {current_user_id}</span></span></code></pre></div><p>When the data is created before the current date:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_posts`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> post_date </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {current_date}</span></span></code></pre></div><p>When the current user creates the data:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_posts`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {current_user_id}</span></span></code></pre></div><p>When the data needs to match with the post title, we can write:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `wp_posts`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> post_title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {current_post_title}</span></span></code></pre></div>',35)])])}const u=e(l,[["render",n]]);export{c as __pageData,u as default};
